# ==============================================================================# 033_RUNTIME_MONITOR.py# ==============================================================================import sqlite3import jsonfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS runtime_monitor(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    total_services INTEGER,    ready INTEGER,    missing INTEGER,    health REAL)""")conn.commit()cur.execute("""SELECT statusFROM runtime""")rows = cur.fetchall()total = len(rows)ready = sum(1 for r in rows if r["status"] == "READY")missing = total - readyhealth = round((ready / total) * 100, 2) if total else 0cur.execute("""INSERT INTO runtime_monitor(    timestamp,    total_services,    ready,    missing,    health)VALUES(?,?,?,?,?)""",(    datetime.now().isoformat(),    total,    ready,    missing,    health))conn.commit()cur.execute("""SELECT *FROM runtime_monitorORDER BY id DESCLIMIT 1""")print("="*80)print("RUNTIME MONITOR")print("="*80)print(json.dumps(dict(cur.fetchone()), indent=4, ensure_ascii=False))print("="*80)conn.close()

